/**
 * {@link FilterOptimizer} placement soundness: a filter may only move into one operand of a Join/LeftJoin when each of
 * its variables is assured there or cannot be bound by the sibling operand, and never below an Extension that
 * overwrites one of its variables. Every rewrite is checked differentially against the unoptimized algebra evaluated
 * with {@link StrictEvaluationStrategy}.
 */
public class FilterPlacementSoundnessTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String PREFIXES = "PREFIX : <urn:t:>\n";

	private static final String OPTIONAL_VARIABLE_ALSO_BOUND_BY_SIBLING = "SELECT ?s ?x ?y WHERE { ?s :p ?y OPTIONAL { ?s :q ?x } ?s :r ?x FILTER(?x = ?y) }";

	private static List<FilterOptimizer> optimizers() {
		return List.of(new FilterOptimizer(), new FilterOptimizer(null, false, false));
	}

	private static Model optionalData() {
		Model data = new LinkedHashModel();
		add(data, "a", "p", VF.createLiteral(1));
		add(data, "a", "r", VF.createLiteral(1));
		add(data, "b", "p", VF.createLiteral(2));
		add(data, "b", "q", VF.createLiteral(2));
		add(data, "b", "r", VF.createLiteral(2));
		add(data, "c", "p", VF.createLiteral(3));
		add(data, "c", "q", VF.createLiteral(4));
		add(data, "c", "r", VF.createLiteral(3));
		return data;
	}

	@Test
	public void keepsFilterAboveJoinWhenOptionalVariableIsAlsoBoundBySibling() {
		Model data = optionalData();
		for (FilterOptimizer optimizer : optimizers()) {
			QueryRoot optimized = optimize(optimizer, OPTIONAL_VARIABLE_ALSO_BOUND_BY_SIBLING, data,
					List.of("s=urn:t:a|x=\"1\"^^<http://www.w3.org/2001/XMLSchema#int>|y=\"1\"^^<http://www.w3.org/2001/XMLSchema#int>",
							"s=urn:t:b|x=\"2\"^^<http://www.w3.org/2001/XMLSchema#int>|y=\"2\"^^<http://www.w3.org/2001/XMLSchema#int>"));
			Filter filter = singleFilter(optimized);
			assertInstanceOf(Join.class, filter.getArg(), "filter must stay above the join\n" + optimized);
		}
	}

	@Test
	public void keepsFilterAboveOuterLeftJoinWhenStackedOptionalsBindTheSameVariable() {
		Model data = new LinkedHashModel();
		add(data, "s1", "p", VF.createIRI("urn:t:o1"));
		add(data, "s1", "r", VF.createIRI("urn:t:v"));
		add(data, "s2", "p", VF.createIRI("urn:t:o2"));
		add(data, "s2", "q", VF.createIRI("urn:t:v"));
		add(data, "s3", "p", VF.createIRI("urn:t:o3"));
		add(data, "s3", "q", VF.createIRI("urn:t:w"));
		add(data, "s3", "r", VF.createIRI("urn:t:v"));
		String query = "SELECT ?s ?x WHERE { ?s :p ?o OPTIONAL { ?s :q ?x } OPTIONAL { ?s :r ?x } FILTER(?x = :v) }";
		for (FilterOptimizer optimizer : optimizers()) {
			QueryRoot optimized = optimize(optimizer, query, data,
					List.of("s=urn:t:s1|x=urn:t:v", "s=urn:t:s2|x=urn:t:v"));
			Filter filter = singleFilter(optimized);
			LeftJoin outer = assertInstanceOf(LeftJoin.class, filter.getArg(),
					"filter must stay above the outer left join\n" + optimized);
			assertInstanceOf(LeftJoin.class, outer.getLeftArg(),
					"filter must stay above both left joins\n" + optimized);
		}
	}

	@Test
	public void pushesFilterOntoPatternNotOntoValuesWithUndefColumn() {
		Model data = new LinkedHashModel();
		add(data, "s1", "p", VF.createIRI("urn:t:v"));
		String query = "SELECT ?s ?x WHERE { VALUES ?x { UNDEF :w } ?s :p ?x FILTER(sameTerm(?x, :v)) }";
		for (FilterOptimizer optimizer : optimizers()) {
			QueryRoot optimized = optimize(optimizer, query, data, List.of("s=urn:t:s1|x=urn:t:v"));
			Filter filter = singleFilter(optimized);
			assertInstanceOf(StatementPattern.class, filter.getArg(),
					"filter must be pushed onto the pattern that assures ?x\n" + optimized);
		}
	}

	@Test
	public void stillPushesFilterIntoOperandThatAssuresAllVariables() {
		Model data = new LinkedHashModel();
		add(data, "s1", "p", VF.createIRI("urn:t:v"));
		add(data, "s1", "r", VF.createIRI("urn:t:a"));
		add(data, "s2", "p", VF.createIRI("urn:t:w"));
		add(data, "s2", "r", VF.createIRI("urn:t:b"));
		String query = "SELECT ?s ?y ?x WHERE { ?s :p ?y . ?s :r ?x FILTER(?y = :v) }";
		for (FilterOptimizer optimizer : optimizers()) {
			QueryRoot optimized = optimize(optimizer, query, data, List.of("s=urn:t:s1|x=urn:t:a|y=urn:t:v"));
			Filter filter = singleFilter(optimized);
			StatementPattern pattern = assertInstanceOf(StatementPattern.class, filter.getArg(),
					"filter must be pushed onto the pattern that assures ?y\n" + optimized);
			assertEquals(VF.createIRI("urn:t:p"), pattern.getPredicateVar().getValue());
		}
	}

	@Test
	public void stillPushesFilterIntoLeftJoinWhenSiblingCannotBindTheVariable() {
		Model data = new LinkedHashModel();
		add(data, "s1", "p", VF.createIRI("urn:t:o"));
		add(data, "s1", "q", VF.createIRI("urn:t:v"));
		add(data, "s1", "r", VF.createIRI("urn:t:a"));
		add(data, "s2", "p", VF.createIRI("urn:t:o"));
		add(data, "s2", "q", VF.createIRI("urn:t:w"));
		add(data, "s2", "r", VF.createIRI("urn:t:b"));
		add(data, "s3", "p", VF.createIRI("urn:t:o"));
		add(data, "s3", "r", VF.createIRI("urn:t:c"));
		String query = "SELECT ?s ?x ?z WHERE { ?s :p ?o OPTIONAL { ?s :q ?x } ?s :r ?z FILTER(?x = :v) }";
		for (FilterOptimizer optimizer : optimizers()) {
			QueryRoot optimized = optimize(optimizer, query, data, List.of("s=urn:t:s1|x=urn:t:v|z=urn:t:a"));
			Filter filter = singleFilter(optimized);
			assertInstanceOf(LeftJoin.class, filter.getArg(),
					"?x cannot be bound by the sibling, so the filter may move onto the left join\n" + optimized);
		}
	}

	@Test
	public void doesNotPushFilterBelowExtensionThatOverwritesFilterVariable() {
		Model data = new LinkedHashModel();
		add(data, "a", "p", VF.createIRI("urn:t:v"));
		IRI v = VF.createIRI("urn:t:v");
		for (FilterOptimizer optimizer : optimizers()) {
			// Filter(?x = :v, Extension(x := ?y, ?s ?y ?x)): the pattern assures ?x but the BIND overwrites it.
			StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("y"), Var.of("x"));
			Extension extension = new Extension(pattern, new ExtensionElem(Var.of("y"), "x"));
			Filter filter = new Filter(extension, new Compare(Var.of("x"), new ValueConstant(v), Compare.CompareOp.EQ));
			QueryRoot root = new QueryRoot(new Projection(filter,
					new ProjectionElemList(new ProjectionElem("s"), new ProjectionElem("x"))));
			QueryRoot expected = root.clone();
			List<String> reference = evaluate(data, root);
			assertEquals(List.of(), reference, "the BIND rewrites ?x to :p, so the filter rejects the row");

			optimizer.optimize(root, null, EmptyBindingSet.getInstance());

			assertEquals(reference, evaluate(data, root), "filter placement changed results\n" + root);
			assertEquals(expected, root, "filter must not move below the overwriting Extension");
		}
	}

	private static QueryRoot optimize(FilterOptimizer optimizer, String query, Model data, List<String> expected) {
		TupleExpr original = parse(query);
		List<String> reference = evaluate(data, original);
		List<String> sortedExpected = new ArrayList<>(expected);
		Collections.sort(sortedExpected);
		assertEquals(sortedExpected, reference, "reference oracle disagrees with the hand-computed bag");
		QueryRoot optimized = new QueryRoot(original.clone());
		optimizer.optimize(optimized, null, EmptyBindingSet.getInstance());
		assertEquals(reference, evaluate(data, optimized), "FilterOptimizer changed results\n" + optimized);
		return optimized;
	}

	private static Filter singleFilter(TupleExpr tupleExpr) {
		List<Filter> filters = new ArrayList<>();
		tupleExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter node) {
				filters.add(node);
				super.meet(node);
			}
		});
		assertEquals(1, filters.size(), "expected exactly one filter\n" + tupleExpr);
		return filters.get(0);
	}

	private static TupleExpr parse(String query) {
		return new SPARQLParser().parseQuery(PREFIXES + query, "urn:t:").getTupleExpr();
	}

	private static List<String> evaluate(Model data, TupleExpr expression) {
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
					Value object, Resource... contexts) {
				return new CloseableIteratorIteration<>(
						data.getStatements(subject, predicate, object, contexts).iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
		QueryRoot root = expression instanceof QueryRoot queryRoot ? queryRoot.clone()
				: new QueryRoot(expression.clone());
		List<String> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> result = new StrictEvaluationStrategy(source, null).precompile(root)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				BindingSet bindings = result.next();
				TreeMap<String, String> sorted = new TreeMap<>();
				for (String name : bindings.getBindingNames()) {
					Value value = bindings.getValue(name);
					if (value != null) {
						sorted.put(name, value.toString());
					}
				}
				StringBuilder builder = new StringBuilder();
				sorted.forEach((name, value) -> {
					if (builder.length() > 0) {
						builder.append('|');
					}
					builder.append(name).append('=').append(value);
				});
				rows.add(builder.toString());
			}
		}
		Collections.sort(rows);
		return rows;
	}

	private static void add(Model model, String subject, String predicate, Value object) {
		model.add(VF.createIRI("urn:t:" + subject), VF.createIRI("urn:t:" + predicate), object);
	}
}
